import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { OrgId, Page, ProjectId } from "@/types/common";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';

/**
 * Denormalised search index kept in step by `SearchService`.
 *
 * An entry is present only while the search rule allows it: a project while it
 * is live; an issue while it and its project are live; a comment while it, its
 * issue and that issue's project are all live. The writers decide that row by
 * row, `pruneIndex` sweeps one org for anything the rule no longer allows, and
 * `searchDocuments` re-applies the rule at query time so a missed write cannot
 * surface a dead subject.
 */
import { and, count, desc, eq, inArray, notInArray, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { livePredicate, orgPredicate } from "./base-repository";
import { comments, getDb, issues, projects, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { SQL } from "drizzle-orm";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/** Removes an issue's entry together with the entries of every comment on it. */
export async function deleteIssueEntries(
  orgId: OrgId,
  issueId: string,
): Promise<void> {
  const db = getDb();
  const issueComments = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "issue"),
            eq(searchIndex.subjectId, issueId),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, issueComments),
          ),
        ),
      ),
    )
    .run();
}

/**
 * Removes a project's entry together with the entries of its issues and of
 * every comment on those issues. Archived issues count too: the cascade must
 * not depend on whether they were archived with the project.
 */
export async function deleteProjectEntries(
  orgId: OrgId,
  projectId: string,
): Promise<void> {
  const db = getDb();
  const projectIssues = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    );
  const projectComments = db
    .select({ id: comments.id })
    .from(comments)
    .innerJoin(issues, eq(issues.id, comments.issueId))
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(issues.projectId, projectId)),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "project"),
            eq(searchIndex.subjectId, projectId),
          ),
          and(
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, projectIssues),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, projectComments),
          ),
        ),
      ),
    )
    .run();
}

/**
 * Drops every entry of one org that the rule no longer allows. Rows belonging
 * to other orgs are never matched: each subquery and the outer delete are
 * scoped to `orgId`.
 */
export async function pruneIndex(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "project"),
            notInArray(searchIndex.subjectId, searchableProjectIds(orgId)),
          ),
          and(
            eq(searchIndex.subjectKind, "issue"),
            notInArray(searchIndex.subjectId, searchableIssueIds(orgId)),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            notInArray(searchIndex.subjectId, searchableCommentIds(orgId)),
          ),
        ),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    searchableEntries(input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Projects the rule allows: live ones. */
function searchableProjectIds(orgId: OrgId) {
  return getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(orgPredicate(projects.orgId, orgId), livePredicate(projects.archivedAt, {})),
    );
}

/** Issues the rule allows: live ones whose project is live. */
function searchableIssueIds(orgId: OrgId) {
  return getDb()
    .select({ id: issues.id })
    .from(issues)
    .innerJoin(projects, eq(projects.id, issues.projectId))
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        livePredicate(issues.archivedAt, {}),
        livePredicate(projects.archivedAt, {}),
      ),
    );
}

/** Comments the rule allows: live ones on live issues in live projects. */
function searchableCommentIds(orgId: OrgId) {
  return getDb()
    .select({ id: comments.id })
    .from(comments)
    .innerJoin(issues, eq(issues.id, comments.issueId))
    .innerJoin(projects, eq(projects.id, issues.projectId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        livePredicate(comments.archivedAt, {}),
        livePredicate(issues.archivedAt, {}),
        livePredicate(projects.archivedAt, {}),
      ),
    );
}

/** The rule as a predicate over index rows: each kind needs its subject to be searchable. */
function searchableEntries(orgId: OrgId): SQL | undefined {
  return or(
    and(
      eq(searchIndex.subjectKind, "project"),
      inArray(searchIndex.subjectId, searchableProjectIds(orgId)),
    ),
    and(
      eq(searchIndex.subjectKind, "issue"),
      inArray(searchIndex.subjectId, searchableIssueIds(orgId)),
    ),
    and(
      eq(searchIndex.subjectKind, "comment"),
      inArray(searchIndex.subjectId, searchableCommentIds(orgId)),
    ),
  );
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';

