/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): reindexProject, pruneIndex
 */
import { createLogger } from "@/lib/logger";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { reindexProject } from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's projects. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks every project in one tenant, re-indexing each project with its live
 * issues and comments, then drops whatever entries the rule no longer allows.
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest.
 *
 * Archived projects are walked too: `reindexProject` removes their content
 * rather than adding it, so the rebuild leaves them out of the index.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    let cursor: string | null = null;
    do {
      const page = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: true,
      });

      for (const project of page.items) {
        try {
          await reindexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      cursor = page.nextCursor;
    } while (cursor !== null);

    await searchRepo.pruneIndex(orgId);
  });
}

