import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { getDb, searchIndex } from "@/server/db";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { registerSearchListeners } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let detach: Unsubscribe;
let t: Tenant;
let other: Tenant;
let admin: Actor;
let member: Actor;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerSearchListeners();
  t = await createTenant("rule", "enterprise");
  other = await createTenant("ruleother", "enterprise");
  admin = t.actors.admin;
  member = t.actors.member;
});

afterAll(() => {
  detach();
  cleanup();
});

function q(text: string, kinds: ("issue" | "comment" | "project")[], tenant: Tenant = t) {
  return searchService.search(tenant.actors.admin, {
    orgId: tenant.org.id,
    q: text,
    kinds,
    limit: 100,
    cursor: null,
  });
}

async function newProject(name: string, key: string) {
  return projectService.createProject(admin, {
    orgId: t.org.id,
    name,
    slug: name.toLowerCase().replace(/\s+/g, "-"),
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function newIssue(projectId: string, title: string) {
  return issueService.createIssue(
    member,
    issueInput(t.org.id, projectId as never, { title }),
  );
}

async function newComment(issueId: string, body: string) {
  return commentService.createComment(member, {
    orgId: t.org.id,
    issueId: issueId as never,
    body,
    parentId: null,
    mentionedUserIds: [],
  });
}

describe("archiving an issue", () => {
  it("removes the issue and every comment on it", async () => {
    const issue = await newIssue(t.project.id, "Alpha1 issue");
    const comment = await newComment(issue.id, "Alpha1 comment");
    expect((await q("Alpha1", ["issue"])).total).toBe(1);
    expect((await q("Alpha1", ["comment"])).total).toBe(1);

    await issueService.archiveIssue(admin, t.org.id, issue.id);

    expect((await q("Alpha1", ["issue"])).total).toBe(0);
    expect((await q("Alpha1", ["comment"])).total).toBe(0);
    void comment;
  });
});

describe("archiving a project", () => {
  for (const archiveIssues of [true, false]) {
    it(`hides project, issues and comments (archiveIssues=${archiveIssues})`, async () => {
      const tag = archiveIssues ? "Bravo" : "Charlie";
      const project = await newProject(`${tag} proj`, tag.slice(0, 3).toUpperCase());
      const issue = await newIssue(project.id, `${tag} issue`);
      await newComment(issue.id, `${tag} comment`);
      expect((await q(tag, ["project"])).total).toBe(1);
      expect((await q(tag, ["issue"])).total).toBe(1);
      expect((await q(tag, ["comment"])).total).toBe(1);

      await projectService.archiveProject(admin, {
        orgId: t.org.id,
        projectId: project.id,
        archiveIssues,
      });

      expect((await q(tag, ["project"])).total).toBe(0);
      expect((await q(tag, ["issue"])).total).toBe(0);
      expect((await q(tag, ["comment"])).total).toBe(0);

      // Writes made afterwards to the kept (or archived) issue stay hidden.
      const late = await newComment(issue.id, `${tag} late comment`);
      await issueService.updateIssue(member, {
        orgId: t.org.id,
        issueId: issue.id,
        title: `${tag} renamed late`,
      });
      await commentService.updateComment(member, {
        orgId: t.org.id,
        commentId: late.id,
        body: `${tag} late edit`,
      });
      expect((await q(tag, ["issue"])).total).toBe(0);
      expect((await q(tag, ["comment"])).total).toBe(0);
      expect((await q("renamed late", ["issue"])).total).toBe(0);
      expect((await q("late edit", ["comment"])).total).toBe(0);
    });
  }
});

describe("restoring a project", () => {
  it("brings back the project and only the issues and comments still live", async () => {
    const project = await newProject("Delta proj", "DEL");
    const archivedBefore = await newIssue(project.id, "Delta before");
    await newComment(archivedBefore.id, "Delta before comment");
    await issueService.archiveIssue(admin, t.org.id, archivedBefore.id);

    const kept = await newIssue(project.id, "Delta kept");
    const keptComment = await newComment(kept.id, "Delta kept comment");
    const deleted = await newComment(kept.id, "Delta deleted comment");
    await commentService.deleteComment(member, { orgId: t.org.id, commentId: deleted.id });
    void keptComment;

    await projectService.archiveProject(admin, {
      orgId: t.org.id,
      projectId: project.id,
      archiveIssues: false,
    });
    expect((await q("Delta", ["project"])).total).toBe(0);
    expect((await q("Delta kept", ["issue"])).total).toBe(0);

    await projectService.restoreProject(admin, t.org.id, project.id);

    expect((await q("Delta proj", ["project"])).total).toBe(1);
    expect((await q("Delta kept", ["issue"])).total).toBe(1);
    expect((await q("Delta kept comment", ["comment"])).total).toBe(1);
    expect((await q("Delta deleted comment", ["comment"])).total).toBe(0);
    expect((await q("Delta before", ["issue"])).total).toBe(0);
    expect((await q("Delta before comment", ["comment"])).total).toBe(0);
  });

  it("does not bring back issues archived together with the project", async () => {
    const project = await newProject("Echo proj", "ECH");
    const issue = await newIssue(project.id, "Echo issue");
    await newComment(issue.id, "Echo comment");

    await projectService.archiveProject(admin, {
      orgId: t.org.id,
      projectId: project.id,
      archiveIssues: true,
    });
    await projectService.restoreProject(admin, t.org.id, project.id);

    expect((await q("Echo proj", ["project"])).total).toBe(1);
    expect((await q("Echo issue", ["issue"])).total).toBe(0);
    expect((await q("Echo comment", ["comment"])).total).toBe(0);
  });
});

describe("rebuilding the index", () => {
  it("restores a large workspace, drops what the rule forbids, and leaves other orgs alone", async () => {
    const big = await newProject("Golf proj", "GLF");
    const ids: string[] = [];
    for (let n = 0; n < 130; n += 1) {
      const issue = await newIssue(big.id, `Golf issue ${n}`);
      ids.push(issue.id);
    }
    const busy = ids[0] as string;
    for (let n = 0; n < 120; n += 1) {
      await newComment(busy, `Golf comment ${n}`);
    }

    const archived = await newIssue(big.id, "Golf archived issue");
    await newComment(archived.id, "Golf archived comment");
    await issueService.archiveIssue(admin, t.org.id, archived.id);

    // Drift: wipe the org's entries, then plant rows the rule forbids.
    getDb().delete(searchIndex).where(eq(searchIndex.orgId, t.org.id)).run();
    await searchRepo.upsertSearchDocument(t.org.id, "issue", archived.id, "Golf archived issue", big.id);
    await searchRepo.upsertSearchDocument(t.org.id, "comment", "ghost-comment", "Golf ghost", null);

    await searchRepo.upsertSearchDocument(other.org.id, "issue", "other-ghost", "Other ghost", null);
    const otherBefore = await searchRepo.countIndexed(other.org.id);

    const result = await runSearchReindexJob(t.org.id);
    expect(result.failed).toBe(0);

    expect((await q("Golf issue", ["issue"])).total).toBe(130);
    expect((await q("Golf comment", ["comment"])).total).toBe(120);
    expect((await q("Golf archived", ["issue", "comment"])).total).toBe(0);
    expect((await q("Golf ghost", ["comment"])).total).toBe(0);
    expect((await q("Golf proj", ["project"])).total).toBe(1);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);
  });
});

